def patch_match(seed, r):
 i,j=seed; p=a[max(0,i-r):min(a.shape[0],i+r+1),max(0,j-r):min(a.shape[1],j+r+1)]
 # normalized patches with zero padding
 pad=np.pad(a,r)
 p=pad[i:i+2*r+1,j:j+2*r+1]
 matches=[]
 for x in range(a.shape[0]):
  for y in range(a.shape[1]):
   if np.array_equal(p,pad[x:x+2*r+1,y:y+2*r+1]): matches.append((x,y))
 return matches
